//
// View model for ServerSelectorView. Holds the in-memory registry, tracks
// modal targets (add / edit / delete / pair), and bridges to the Rust core
// via the UniFFI-generated `clientPair` / `startVideoStream` symbols.
//
// **Untested on macOS** — see ServerSelectorView.swift for the verification
// checklist. The bindings file generated by uniffi-bindgen lives at
// `client/shared/generated/swift/Trireme.swift` and must be added to the
// Xcode target. If the function names below don't match the generated
// signatures, adjust here (Swift's camelCasing of Rust snake_case can
// shift between uniffi versions).

import Foundation
import SwiftUI

@MainActor
public final class ServerSelectorModel: ObservableObject {
    @Published public var registry: Registry
    @Published public var selected: Set<String> = []
    @Published public var showAdd: Bool = false
    @Published public var editing: ServerEntry?
    @Published public var deleting: ServerEntry?
    @Published public var pairing: ServerEntry?

    private let store: ServerStore

    public init(store: ServerStore = ServerStore()) {
        self.store = store
        self.registry = store.load()
    }

    public func tap(_ server: ServerEntry) {
        if !selected.isEmpty {
            toggleSelect(server.id)
        } else {
            connect([server])
        }
    }

    public func toggleSelect(_ id: String) {
        if selected.contains(id) { selected.remove(id) } else { selected.insert(id) }
    }

    public func clearSelection() { selected.removeAll() }

    public func connectSelected() {
        connect(selected.compactMap { registry.find($0) })
    }

    private func connect(_ entries: [ServerEntry]) {
        guard let pick = entries.first else { return }
        // TODO: when the player view is in place, present it here with the
        // chosen host + pinned pubkey. For now we just record the action.
        NotificationCenter.default.post(
            name: .triremeRequestConnect,
            object: nil,
            userInfo: [
                "host": "\(pick.host):\(pick.port)",
                "hostPubkey": pick.hostPubkey ?? "",
            ]
        )
    }

    public func addOrUpdate(host: String, port: Int, alias: String, replacing oldId: String?) {
        let id = ServerEntry.makeId(host: host, port: port)
        let trimmedAlias = alias.trimmingCharacters(in: .whitespaces)
        // Preserve paired/cache state when the host/port changes.
        let existing = oldId.flatMap { registry.find($0) } ?? registry.find(id)
        let updated = ServerEntry(
            id: id,
            host: host,
            port: port,
            alias: trimmedAlias.isEmpty ? nil : trimmedAlias,
            hostnameCache: existing?.hostnameCache,
            pace: existing?.pace,
            paired: existing?.paired ?? false,
            hostPubkey: existing?.hostPubkey,
            pairPort: existing?.pairPort,
            lastConnected: existing?.lastConnected
        )
        var next = registry
        if let oldId, oldId != id { next = next.remove(oldId) }
        next = next.upsert(updated)
        registry = next
        store.save(next)
    }

    public func delete(id: String) {
        let next = registry.remove(id)
        registry = next
        selected.remove(id)
        store.save(next)
    }

    public func runPair(
        target: ServerEntry,
        pin: String,
        completion: @escaping (Result<String, Error>) -> Void
    ) {
        let addr = "\(target.host):\(target.pairPortOrDefault())"
        let identityPath = store.identityPath()
        // The Rust side runs its own runtime inside clientPair; offload to a
        // background queue so the UI stays responsive.
        Task.detached(priority: .userInitiated) { [weak self] in
            do {
                // The UniFFI-generated symbol on iOS is `clientPair`. Adjust
                // here if your bindings emit a different name.
                let result = try clientPair(
                    addr: addr,
                    pin: pin,
                    identityPath: identityPath,
                    ourAlias: ProcessInfo.processInfo.hostName
                )
                await MainActor.run {
                    self?.applyPaired(target: target, result: result)
                    completion(.success(result.hostPubkeyHex))
                }
            } catch {
                await MainActor.run {
                    completion(.failure(error))
                }
            }
        }
    }

    private func applyPaired(target: ServerEntry, result: PairResult) {
        var entry = target
        entry.paired = true
        entry.hostPubkey = result.hostPubkeyHex
        entry.pairPort = target.pairPortOrDefault()
        if entry.alias == nil { entry.alias = result.hostAlias }
        let next = registry.upsert(entry)
        registry = next
        store.save(next)
    }
}

public extension Notification.Name {
    /// Posted when the selector wants to open a stream. The app shell wires
    /// this up to whatever player surface is current.
    static let triremeRequestConnect = Notification.Name("io.github.cursednumber.trireme.requestConnect")
}
